css:
.rp { background: var(--card); border: 1px solid var(--line); border-top: 3px solid var(--accent); border-radius: var(--radius-card); padding: 22px; display: flex; flex-direction: column; gap: 4px; }
.rp__h { margin: 0 0 10px; font: 700 26px/1.1 var(--font-heading); text-transform: uppercase; color: var(--accent); }
.rp__i { display: grid; grid-template-columns: 72px minmax(0, 1fr); gap: 12px; padding: 12px 8px; margin: 0 -8px; border-top: 1px solid var(--line); border-radius: var(--radius-input); text-decoration: none; align-items: start; transition: background var(--hcm-dur) var(--hcm-ease); }
.rp__i:hover { background: var(--hcm-tint); }
.rp__i img, .rp__blank { width: 72px; height: 56px; object-fit: cover; border-radius: var(--radius-input); display: block; }
.rp__blank { background: var(--accent); }
.rp__t { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.rp__c { font: 700 11px/1.3 var(--font-body); letter-spacing: .1em; text-transform: uppercase; color: var(--muted); }
.rp__n { font: 700 17px/1.15 var(--font-heading); color: var(--ink-dark, var(--accent)); }
.rp__m { font: 600 13px/1.3 var(--font-body); color: var(--accent); }
